pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(c));
        vm.assume(caller != address(0));
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        assertTrue(success == (caller == c.admin()));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        address ownerBefore = c.owner();
        (bool success, ) = address(c).call(abi.encodeCall(c.setOwner, (newOwner)));
        address ownerAfter = c.owner();
        assertTrue(success ? ownerAfter == ownerBefore : ownerAfter == ownerBefore);
    }
}

